# Not in the book: pairing prompts with kept responses for fit()
kept = {"prompts": [], "responses": []}
for p, r, s in zip(prompts, responses, rewards):
    if s > cutoff:
        kept["prompts"].append(p)
        kept["responses"].append(r)
model.fit(tf.data.Dataset.from_tensor_slices(kept).batch(2))
